"use strict";(self.webpackChunkWebGL=self.webpackChunkWebGL||[]).push([[678],{9937:(n,t,e)=>{e.r(t),e.d(t,{default:()=>a});e(5043);var i=e(8044),o=e(579);const a=function(){return(0,o.jsx)(i.A,{srcDoc:'## \u7b80\u5355\u7684\u6570\u5b66\u77e5\u8bc6\n\n\u5728\u5b9e\u73b0\u65cb\u8f6c\u524d\uff0c\u6211\u4eec\u5148\u770b\u4e0b\u9762\u4e00\u9053\u9898\uff0c\u5df2\u77e5\u70b9A(x1, y1)\uff0c\u6c42\u70b9A\u65cb\u8f6c30\u5ea6\u540e\u7684\u70b9B(x2, y2)\n\n![image](../../easy-webgl/rotate_01.jpg)\n\n\n\u8ba1\u7b97\u8fc7\u7a0b\u5982\u4e0b\uff1a\n\n![image](../../easy-webgl/rotate_02.jpg)\n\n\n\u56e0\u6b64\uff0c\u53ef\u4ee5\u5f97\u51fa\u4e0b\u9762\u7684\u516c\u5f0f\uff0c\u5176\u4e2dB\u5c31\u662f\u65cb\u8f6c\u7684\u5f27\u5ea6\u3002\n\n```js\nx2 = x1 * cosB + y1 * sinB;\ny2 = y1 * cosB - x1 * sinB;\n```\n\n\n## \u4e8c\u7ef4\u65cb\u8f6c\n\u57fa\u4e8e\u4e0a\u9762\u7684\u516c\u5f0f\uff0c\u6211\u4eec\u53ef\u4ee5\u5f88\u5bb9\u6613\u6c42\u51facosB\u548csinB\n```js\nvar angleInDegrees = 360 - ui.value;\nvar angleInRadians = (angleInDegrees * Math.PI) / 180;\nrotation[0] = Math.sin(angleInRadians);\nrotation[1] = Math.cos(angleInRadians);\n```\n\n\u7136\u540e\u5728\u9876\u70b9\u7740\u8272\u5668\u4e2d\uff0c\u5c06\u8ba1\u7b97\u540e\u7684\u503c\u4f20\u7ed9\u9876\u70b9\u7740\u8272\u5668\u3002\n\n```js\nvec2 rotatedPosition = vec2(a_position.x * u_rotation.y + a_position.y * u_rotation.x, a_position.y * u_rotation.y - a_position.x * u_rotation.x);\n\n```\n\n\u7ed3\u679c\u5982\u4e0b\uff1a\n\n![image](../../easy-webgl/rotate_03.jpg)\n\n\n## \u5b8c\u6574\u4ee3\u7801\n\u5b8c\u6574\u4ee3\u7801\u5982\u4e0b\uff1a\n\n```html\n<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1" />\n    <meta name="theme-color" content="#000000" />\n    <meta name="description" content="WebGL" />\n    <title>WebGL</title>\n    <style>\n      @import url("./webgl-tutorials.css");\n\n      body {\n        margin: 20px;\n      }\n\n      #webgl {\n        width: 500px;\n        height: 500px;\n      }\n\n      .container {\n        font-size: 0;\n        display: inline-block;\n        /* border: 1px solid black; */\n      }\n\n      #ui {\n        width: 200px;\n      }\n    </style>\n  </head>\n\n  <body>\n    <div id="uiContainer">\n      <div id="ui">\n        <div id="x"></div>\n        <div id="y"></div>\n        <div id="angle"></div>\n      </div>\n    </div>\n    <div class="container">\n      <canvas width="500" height="500" id="webgl"\n        >\u4f60\u7684\u6d4f\u89c8\u5668\u4e0d\u652f\u6301canvas</canvas\n      >\n    </div>\n    <script src="./webgl-lessons-ui.js"><\/script>\n\n    <script src="./initShaders.js"><\/script>\n    <script>\n      const main = (image) => {\n        const canvas = document.getElementById("webgl");\n\n        const gl = canvas.getContext("webgl");\n        const vertexShaderSource1 = `\n        attribute vec2 a_position;\n        uniform vec2 u_translation;\n        uniform vec2 u_rotation;\n        void main(){\n            gl_PointSize = 10.0;\n            vec2 rotatedPosition = vec2(a_position.x * u_rotation.y + a_position.y * u_rotation.x, a_position.y * u_rotation.y - a_position.x * u_rotation.x);\n            vec2 position = rotatedPosition + u_translation;\n            gl_Position = vec4(position, 0.0, 1.0);\n        }\n      `;\n        const fragmentShaderSource1 = `\n        precision mediump float;\n        void main(){\n          gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\n        }\n      `;\n        const program1 = initShaders(\n          gl,\n          vertexShaderSource1,\n          fragmentShaderSource1\n        );\n        const positionLocation1 = gl.getAttribLocation(program1, "a_position");\n        const translationLocation = gl.getUniformLocation(\n          program1,\n          "u_translation"\n        );\n        const rotationLocation = gl.getUniformLocation(program1, "u_rotation");\n        const rectX = 0,\n          rectY =0,\n          rectWidth = 0.5,\n          rectHeight = 0.8,\n          thickness = 0.1;\n        let verticesInfo = [\n          // \u5de6\u7ad6\n          rectX,\n          rectY,\n          rectX + thickness,\n          rectY,\n          rectX,\n          rectY - rectHeight,\n          rectX,\n          rectY - rectHeight,\n          rectX + thickness,\n          rectY,\n          rectX + thickness,\n          rectY - rectHeight,\n          // \u4e0a\u6a2a\n          rectX + thickness,\n          rectY,\n          rectX + thickness,\n          rectY - thickness,\n          rectX + rectWidth,\n          rectY,\n          rectX + rectWidth,\n          rectY,\n          rectX + rectWidth,\n          rectY - thickness,\n          rectX + thickness,\n          rectY - thickness,\n          // \u4e2d\u6a2a\n          rectX + thickness,\n          rectY - 0.3,\n          rectX + thickness,\n          rectY - 0.3 - thickness,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3,\n          rectX + thickness,\n          rectY - 0.3 - thickness,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3 - thickness,\n        ];\n\n        verticesInfo = new Float32Array(verticesInfo);\n\n        const vertexBuffer = gl.createBuffer();\n        gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);\n        gl.bufferData(gl.ARRAY_BUFFER, verticesInfo, gl.STATIC_DRAW);\n\n        gl.vertexAttribPointer(positionLocation1, 2, gl.FLOAT, false, 8, 0);\n\n        gl.enableVertexAttribArray(positionLocation1);\n\n        gl.clearColor(0, 0, 0, 0);\n\n        gl.clear(gl.COLOR_BUFFER_BIT);\n\n        gl.useProgram(program1);\n\n        var translation = [0, 0];\n        var rotation = [0, 1];\n        gl.uniform2fv(rotationLocation, rotation);\n        gl.uniform2fv(translationLocation, translation);\n\n        function updatePosition(index) {\n          return function (event, ui) {\n            const v =\n              (index === 0\n                ? ui.value / (gl.canvas.width + 5)\n                : -ui.value / (gl.canvas.height + 5)) * 2;\n            translation[index] = v;\n            gl.uniform2fv(translationLocation, translation);\n            gl.drawArrays(gl.TRIANGLES, 0, 18);\n          };\n        }\n        function updateAngle(event, ui) {\n          var angleInDegrees = 360 - ui.value;\n          var angleInRadians = (angleInDegrees * Math.PI) / 180;\n          rotation[0] = Math.sin(angleInRadians);\n          rotation[1] = Math.cos(angleInRadians);\n          gl.uniform2fv(rotationLocation, rotation);\n          gl.drawArrays(gl.TRIANGLES, 0, 18);\n        }\n        webglLessonsUI.setupSlider("#x", {\n          slide: updatePosition(0),\n          max: gl.canvas.width,\n        });\n        webglLessonsUI.setupSlider("#y", {\n          slide: updatePosition(1),\n          max: gl.canvas.height,\n        });\n        webglLessonsUI.setupSlider("#angle", { slide: updateAngle, max: 360 });\n\n        gl.drawArrays(gl.TRIANGLES, 0, 18);\n      };\n\n      main();\n    <\/script>\n  </body>\n</html>\n\n```'})}}}]);
